// stack-dataflow-corpus.mjs — corpus writer for the Engine Room data loop (flow.* keys).
// Idempotent: inserts or refreshes ONLY flow.* keys in surfaces/lang-corpus.json; every
// other key is preserved byte-for-byte (the file round-trips through JSON.stringify(,null,1),
// verified stable). Every non-name key MUST carry all 28 docked tongues or the writer
// refuses — the corpus law (a tongue that carries half the corpus looks translated and is not).
// Board-chip labels (flow.b.*) are the receipt's own record-of-origin vocabulary: names
// never translated (pointer principle) — their cells are identical across tongues by law.
//
//   node scripts/stack-dataflow-corpus.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CORPUS = join(ROOT, 'surfaces/lang-corpus.json');
const LANGS = ['ru','lv','th','gd','tt','uk','cs','zh','ko','ar','nl-be','es','nl','de','fr','he','hi','bn','fa','ur','ja','da','nb','sv','fi','tr','hu','sa'];

// names never translated — identical cells in every tongue (kandi law shape)
const NAME_CONST = new Set(['flow.b.intake','flow.b.play','flow.b.tv','flow.b.quote','flow.b.upload','flow.b.playable','flow.b.retrieval','flow.b.boundary','flow.b.authority']);

